theorem exI_sound {p : String} {Γ : List PLLFormula}
    (hΓ : ∀ ψ ∈ Γ, PLLND.isIPL ψ) : PLLND.SemUI.Deriv Γ (exI p Γ)

/-- The same statement at the working judgment `G4c = ∃ n, G4h n`. -/
theorem toG4_isIPL {Γ : List PLLFormula} {C : PLLFormula}
    (d : G4c Γ C) (hΓ : ∀ ψ ∈ Γ, isIPL ψ) (hC : isIPL C) : G4 Γ C

/-- **The `◯`-free fragment of G4iLL is exactly IPC.** -/
theorem iff_IPLND {Γ : List PLLFormula} {C : PLLFormula}
    (hΓ : ∀ ψ ∈ Γ, isIPL ψ) (hC : isIPL C) : G4 Γ C ↔ IPLND Γ C

theorem valid_erase {K : Kripke} {G : Form}
    (hRm : ∀ {a u : K.W}, K.Rm a u → u = a) :
    K.valid (erase G) ↔ K.valid G

/-- Transparency IS cone-triviality at every world. -/
theorem coneTrivial_of_transparent {K : Kripke}
    (hRm : ∀ {a u : K.W}, K.Rm a u → u = a) (b : K.W) : K.ConeTrivial b

theorem circPart_lamStar_nil_of_transparent {K : Kripke}
    (hRm : ∀ {a u : K.W}, K.Rm a u → u = a) (b : K.W) (G : Form) :
    circPart (lamStar K b G) = []
